import{_ as d,o,c as e,ag as a}from"./chunks/framework.KxDd3USm.js";const l=JSON.parse('{"title":"07.3 前缀、中缀、后缀表达式 ★★","description":"","frontmatter":{},"headers":[],"relativePath":"07-程序设计语言基础/03-表达式与语法树.md","filePath":"07-程序设计语言基础/03-表达式与语法树.md"}'),c={name:"07-程序设计语言基础/03-表达式与语法树.md"};function s(n,t,r,p,b,g){return o(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="_07-3-前缀、中缀、后缀表达式-★★" tabindex="-1">07.3 前缀、中缀、后缀表达式 ★★ <a class="header-anchor" href="#_07-3-前缀、中缀、后缀表达式-★★" aria-label="Permalink to &quot;07.3 前缀、中缀、后缀表达式 ★★&quot;">​</a></h1><p>这一节第 1 课（<a href="/ruankao/01-数据结构与算法/01-线性表、栈与队列.html">线性表、栈与队列</a> 第 1.2 节）已详细讲过中缀转后缀的&quot;傻瓜法&quot;（按优先级加满括号，运算符搬到自己那对括号的右边）。这里给速查表和<strong>前缀</strong>补全：</p><table tabindex="0"><thead><tr><th>表达式</th><th>运算符位置</th><th>例子（(a+b)*c−d）</th><th>特点</th></tr></thead><tbody><tr><td>中缀</td><td>两操作数<strong>中间</strong></td><td><code>(a+b)*c−d</code></td><td>人习惯，需括号和优先级</td></tr><tr><td><strong>后缀（逆波兰式）</strong></td><td>两操作数<strong>后面</strong></td><td><code>ab+c*d−</code></td><td>计算机求值最方便，无括号</td></tr><tr><td><strong>前缀（波兰式）</strong></td><td>两操作数<strong>前面</strong></td><td><code>−*+abcd</code></td><td>无括号，考试较少考</td></tr></tbody></table><h3 id="_4-1-语法树遍历与三种表达式" tabindex="-1">4.1 语法树遍历与三种表达式 <a class="header-anchor" href="#_4-1-语法树遍历与三种表达式" aria-label="Permalink to &quot;4.1 语法树遍历与三种表达式&quot;">​</a></h3><p>表达式树把“谁先算”直接画成父子关系：内部结点是运算符，叶子是操作数。对 <code>(a+b)*c</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        *</span></span>
<span class="line"><span>       / \\</span></span>
<span class="line"><span>      +   c</span></span>
<span class="line"><span>     / \\</span></span>
<span class="line"><span>    a   b</span></span></code></pre></div><p>同一棵树用不同遍历顺序读，就得到三种等价写法：</p><table tabindex="0"><thead><tr><th>遍历</th><th>访问次序</th><th>结果</th><th>表达式</th></tr></thead><tbody><tr><td>先序</td><td>根—左—右</td><td><code>* + a b c</code></td><td>前缀 <code>*+abc</code></td></tr><tr><td>中序</td><td>左—根—右</td><td><code>a + b * c</code>，按树补括号</td><td>中缀 <code>(a+b)*c</code></td></tr><tr><td>后序</td><td>左—右—根</td><td><code>a b + c *</code></td><td>后缀 <code>ab+c*</code></td></tr></tbody></table><p><strong>为什么中序必须按树补括号</strong>：若只把中序字符机械写成 <code>a+b*c</code>，常规优先级会先算 <code>b*c</code>，与树中“先算 a+b”矛盾。树已经规定运算结构，中缀式必须用括号把这层结构保留下来。</p><p><strong>反例演示（易错）</strong>：有人把这棵树的后缀写成 <code>bc+a*</code>。按后缀规则还原：<code>bc+</code> 先得到 <code>(b+c)</code>，再与 a 相乘，实际是 <code>(b+c)*a</code>，不是 <code>(a+b)*c</code>。错误版本不是“顺序差一点”，而是换了一棵树、改变了运算含义。</p><p><strong>应试动作</strong>：见“给语法树求表达式”直接套：先序=前缀，中序=中缀，后序=后缀；中序读完按树补括号。写完把后缀用栈还原一次，确认每个运算符吃到的左右子树正确。</p><p><strong>转前缀的傻瓜法</strong>：同样先加满括号，把运算符搬到自己那对括号的<strong>左边</strong>。例：<code>(a+b)*c−d</code> → <code>(((a+b)*c)−d)</code> → <code>+ab</code> 变 <code>+ab</code>，<code>(+ab)c</code> 变 <code>*+abc</code>，整体减 d → <code>−*+abcd</code>。</p><p><strong>后缀求值（必考，完整步骤）</strong>：从左到右扫，<strong>操作数进栈；遇运算符弹出栈顶两个数计算——先弹出的是右操作数——结果再进栈</strong>。例：后缀 <code>8 2 3 * − 4 +</code>：</p><table tabindex="0"><thead><tr><th>读到</th><th>动作</th><th>栈</th></tr></thead><tbody><tr><td>8, 2, 3</td><td>依次进栈</td><td>8, 2, 3</td></tr><tr><td><code>*</code></td><td>弹 3、弹 2，算 2×3=6，进栈</td><td>8, 6</td></tr><tr><td><code>−</code></td><td>弹 6、弹 8，算 <strong>8−6</strong>=2，进栈</td><td>2</td></tr><tr><td>4</td><td>进栈</td><td>2, 4</td></tr><tr><td><code>+</code></td><td>弹 4、弹 2，算 2+4=6</td><td>6</td></tr></tbody></table><p>结果 6。<strong>反向验证</strong>：该后缀对应中缀 <code>8−2*3+4</code> = 8−6+4 = <strong>6</strong> ✓。</p><p><strong>为什么编译器爱用后缀做中间代码</strong>：第三节说过中间代码常用形式里就有&quot;后缀式&quot;——扫后缀式时每个运算符出现时它的操作数一定已在栈里，一遍扫完，不需要优先级表和括号。</p><p><strong>反例演示</strong>：后缀求值时<strong>先弹的是右操作数</strong>，减法除法顺序不能反。<code>8 6 −</code> 是 8−6=2；若先弹的当左操作数就算成 6−8=−2，错。</p><p><strong>应试动作</strong>：① 中缀转后缀用&quot;加满括号搬右边&quot;，转前缀&quot;搬左边&quot;；② 求值时先弹的当<strong>右</strong>操作数；③ 考题给后缀式求值，用栈表逐步算，算完还原成中缀验一遍。</p>`,18)])])}const i=d(c,[["render",s]]);export{l as __pageData,i as default};
